const std = @import("std");
const h = @import("headers.zig");

pub const Mailbox = struct { name: []const u8, address: []const u8 };
pub const Address = struct { group: bool = false, mailbox: ?Mailbox = null, members: []Mailbox = &.{} };
pub const Addresses = struct { items: []Address, encoding_error: bool };

fn dotAtom(tokens: []const h.Token) bool {
    if (tokens.len == 0 or tokens.len % 2 == 0) return false;
    for (tokens, 0..) |token, i| if (token.kind != (if (i % 2 == 0) h.word_kind else '.')) return false;
    return true;
}

fn addressString(local: []const h.Token, domain: []const h.Token) ?[]const u8 {
    if (!dotAtom(local) or !dotAtom(domain)) return null;
    var text: h.Text = .{};
    for (local) |token| text.write(token.text);
    text.write("@");
    for (domain) |token| text.write(token.text);
    return h.lowercase(text.value());
}

const Parser = struct {
    tokens: []const h.Token,
    position: usize = 0,
    encoding_error: bool = false,

    fn peek(self: Parser) u16 {
        return if (self.position < self.tokens.len) self.tokens[self.position].kind else 0;
    }

    fn expect(self: *Parser, kind: u16) bool {
        if (self.peek() != kind) return false;
        self.position += 1;
        return true;
    }

    fn displayName(self: *Parser, phrase: []const h.Token) []const u8 {
        var text: h.Text = .{};
        var previous = false;
        for (phrase, 0..) |token, i| {
            const word = if (token.kind == h.word_kind) h.decodeWord(token.text) else h.DecodedWord{ .text = token.text };
            if (i > 0 and token.spaced and !(word.decoded and previous)) text.write(" ");
            text.write(word.text);
            previous = word.decoded;
            self.encoding_error = self.encoding_error or word.failed;
        }
        return h.collapseWhitespace(text.value());
    }

    fn parseAddress(self: *Parser, in_group: bool) ?Address {
        const phrase_start = self.position;
        while (self.peek() == h.word_kind or self.peek() == h.quoted_kind or self.peek() == '.') self.position += 1;
        const phrase = self.tokens[phrase_start..self.position];
        if (self.peek() == '<') {
            self.position += 1;
            const local_start = self.position;
            while (self.peek() == h.word_kind or self.peek() == '.') self.position += 1;
            const local = self.tokens[local_start..self.position];
            if (!self.expect('@')) return null;
            const domain_start = self.position;
            while (self.peek() == h.word_kind or self.peek() == '.') self.position += 1;
            const domain = self.tokens[domain_start..self.position];
            if (!self.expect('>')) return null;
            const address = addressString(local, domain) orelse return null;
            return .{ .mailbox = .{ .name = self.displayName(phrase), .address = address } };
        }
        if (self.peek() == '@') {
            self.position += 1;
            const domain_start = self.position;
            while (self.peek() == h.word_kind or self.peek() == '.') self.position += 1;
            const address = addressString(phrase, self.tokens[domain_start..self.position]) orelse return null;
            return .{ .mailbox = .{ .name = "", .address = address } };
        }
        if (self.peek() == ':' and phrase.len > 0 and !in_group) {
            self.position += 1;
            var members: std.ArrayList(Mailbox) = .empty;
            if (self.peek() != ';') {
                while (true) {
                    const member = self.parseAddress(true) orelse return null;
                    h.append(Mailbox, &members, member.mailbox.?);
                    if (self.peek() != ',') break;
                    self.position += 1;
                }
            }
            if (!self.expect(';')) return null;
            return .{ .group = true, .members = members.items };
        }
        return null;
    }
};

pub fn parse(source: []const u8) ?Addresses {
    const tokens = h.tokenize(source, false) orelse return null;
    if (tokens.len == 0) return null;
    var parser: Parser = .{ .tokens = tokens };
    var items: std.ArrayList(Address) = .empty;
    while (true) {
        h.append(Address, &items, parser.parseAddress(false) orelse return null);
        if (parser.peek() != ',') break;
        parser.position += 1;
    }
    if (parser.position != tokens.len) return null;
    return .{ .items = items.items, .encoding_error = parser.encoding_error };
}

const h = @import("headers.zig");

pub const Date = struct { seconds: ?i64 = null, error_text: ?[]const u8 = null };

fn leap(year: i64) bool {
    return (@mod(year, 4) == 0 and @mod(year, 100) != 0) or @mod(year, 400) == 0;
}

fn monthDays(year: i64, month: i64) i64 {
    const lengths = [_]i64{ 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };
    return if (month == 2 and leap(year)) 29 else lengths[h.u(month - 1)];
}

fn yearDays(year: i64) i64 {
    return if (leap(year)) 366 else 365;
}

fn digits(text: []const u8, first: usize, second: usize) bool {
    if (text.len != first and text.len != second) return false;
    for (text) |character| if (character < '0' or character > '9') return false;
    return true;
}

pub fn parse(source: []const u8) Date {
    const syntax: Date = .{ .error_text = "bad Date syntax" };
    const range: Date = .{ .error_text = "Date out of range" };
    const weekdays = [_][]const u8{ "mon", "tue", "wed", "thu", "fri", "sat", "sun" };
    const months = [_][]const u8{ "jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec" };
    const zones = [_][]const u8{ "ut", "gmt", "z", "est", "edt", "cst", "cdt", "mst", "mdt", "pst", "pdt" };
    const offsets = [_]i64{ 0, 0, 0, -300, -240, -360, -300, -420, -360, -480, -420 };
    const clean = h.removeComments(source) orelse return syntax;
    var spaced: h.Text = .{};
    for (clean) |character| {
        if (character == ',') spaced.write(" , ") else spaced.add("{c}", .{character});
    }
    const tokens = h.splitWords(spaced.value());
    var weekday: ?usize = null;
    var start: usize = 0;
    if (tokens.len >= 3 and h.eq(tokens[1], ",")) {
        for (weekdays, 0..) |name, i| if (h.equalCase(tokens[0], name)) { weekday = i; };
        if (weekday != null) start = 2;
    }
    if (tokens.len - start != 5) return syntax;
    const day_text = tokens[start];
    const month_text = tokens[start + 1];
    const year_text = tokens[start + 2];
    const time = h.split(tokens[start + 3], ':');
    const zone = tokens[start + 4];
    var month: i64 = 0;
    var zone_index: ?usize = null;
    for (months, 0..) |name, i| if (h.equalCase(month_text, name)) { month = h.n(i + 1); };
    for (zones, 0..) |name, i| if (h.equalCase(zone, name)) { zone_index = i; };
    const numeric_zone = zone.len == 5 and (zone[0] == '+' or zone[0] == '-') and digits(zone[1..], 4, 4);
    var time_valid = time.len == 2 or time.len == 3;
    for (time) |part| if (!digits(part, 2, 2)) { time_valid = false; };
    if (!digits(day_text, 1, 2) or month == 0 or !digits(year_text, 2, 4) or !time_valid or (!numeric_zone and zone_index == null)) return syntax;
    var year = h.number(year_text);
    if (year_text.len == 2) year += if (year < 50) @as(i64, 2000) else 1900;
    const day = h.number(day_text);
    const hour = h.number(time[0]);
    const minute = h.number(time[1]);
    const second = if (time.len == 3) h.number(time[2]) else 0;
    var offset: i64 = undefined;
    if (numeric_zone) {
        const hours = h.number(zone[1..3]);
        const minutes = h.number(zone[3..]);
        if (hours > 23 or minutes > 59) return range;
        offset = hours * 60 + minutes;
        if (zone[0] == '-') offset = -offset;
    } else offset = offsets[zone_index.?];
    if (year < 1970 or year > 2099 or day < 1 or day > monthDays(year, month) or hour > 23 or minute > 59 or second > 59) return range;
    var days: i64 = 0;
    var current: i64 = 1970;
    while (current < year) : (current += 1) days += yearDays(current);
    current = 1;
    while (current < month) : (current += 1) days += monthDays(year, current);
    days += day - 1;
    const seconds = days * 86400 + hour * 3600 + minute * 60 + second - offset * 60;
    if (seconds < 0) return range;
    if (weekday) |value| if (@mod(days + 3, 7) != h.n(value)) return .{ .error_text = "Date weekday mismatch" };
    return .{ .seconds = seconds };
}

pub fn formatUtc(seconds: i64) []const u8 {
    var days = @divTrunc(seconds, 86400);
    const rest = @mod(seconds, 86400);
    var year: i64 = 1970;
    var month: i64 = 1;
    while (days >= yearDays(year)) : (year += 1) days -= yearDays(year);
    while (days >= monthDays(year, month)) : (month += 1) days -= monthDays(year, month);
    return h.fmt("{d:0>4}-{d:0>2}-{d:0>2} {d:0>2}:{d:0>2}:{d:0>2}", .{ year, month, days + 1, @divTrunc(rest, 3600), @divTrunc(@mod(rest, 3600), 60), @mod(rest, 60) });
}

const std = @import("std");
const mime = @import("mime.zig");
pub var allocator: std.mem.Allocator = undefined;
pub const Strings = []const []const u8;
pub fn alloc(comptime T: type, count: usize) []T { return allocator.alloc(T, count) catch @panic("allocation failed"); }
pub fn append(comptime T: type, list: *std.ArrayList(T), value: T) void { list.append(allocator, value) catch @panic("allocation failed"); }
pub fn fmt(comptime pattern: []const u8, arguments: anytype) []const u8 { return std.fmt.allocPrint(allocator, pattern, arguments) catch @panic("allocation failed"); }
pub fn eq(first: []const u8, second: []const u8) bool { return std.mem.eql(u8, first, second); }
pub fn n(value: anytype) i64 { return @intCast(value); }
pub fn u(value: i64) usize { return @intCast(value); }
pub fn number(source: []const u8) i64 { return std.fmt.parseInt(i64, source, 10) catch unreachable; }
pub fn whitespace(character: u8) bool { return character == ' ' or character == '\t'; }
pub fn lowerCharacter(character: u8) u8 { return if (character >= 'A' and character <= 'Z') character + 'a' - 'A' else character; }
pub fn lowercase(source: []const u8) []const u8 {
    const result = alloc(u8, source.len);
    for (source, result) |character, *target| target.* = lowerCharacter(character);
    return result;
}
pub fn equalCase(first: []const u8, second: []const u8) bool {
    if (first.len != second.len) return false;
    for (first, second) |a, b| if (lowerCharacter(a) != lowerCharacter(b)) return false;
    return true;
}
pub fn split(source: []const u8, separator: u8) Strings {
    var result: std.ArrayList([]const u8) = .empty;
    var iterator = std.mem.splitScalar(u8, source, separator);
    while (iterator.next()) |part| append([]const u8, &result, part);
    return result.items;
}
pub fn lines(source: []const u8) Strings { const result = split(source, '\n'); return result[0 .. result.len - 1]; }
pub fn splitWords(source: []const u8) Strings {
    var result: std.ArrayList([]const u8) = .empty;
    var iterator = std.mem.tokenizeAny(u8, source, " \t");
    while (iterator.next()) |word| append([]const u8, &result, word);
    return result.items;
}
pub fn join(source: Strings, separator: []const u8) []const u8 {
    var text: Text = .{};
    for (source, 0..) |item, i| { if (i > 0) text.write(separator); text.write(item); }
    return text.value();
}
pub fn collapseWhitespace(source: []const u8) []const u8 { return join(splitWords(source), " "); }
pub fn strip(source: []const u8) []const u8 { return std.mem.trim(u8, source, " \t"); }
pub fn rstrip(source: []const u8) []const u8 { return std.mem.trimEnd(u8, source, " \t"); }
pub const Text = struct {
    data: std.ArrayList(u8) = .empty,
    pub fn write(self: *Text, source: []const u8) void { self.data.appendSlice(allocator, source) catch @panic("allocation failed"); }
    pub fn add(self: *Text, comptime pattern: []const u8, arguments: anytype) void { self.write(fmt(pattern, arguments)); }
    pub fn value(self: Text) []const u8 { return self.data.items; }
};
pub const Lines = struct {
    data: std.ArrayList([]const u8) = .empty,
    pub fn write(self: *Lines, source: []const u8) void { append([]const u8, &self.data, source); }
    pub fn add(self: *Lines, comptime pattern: []const u8, arguments: anytype) void { self.write(fmt(pattern, arguments)); }
    pub fn paragraph(self: *Lines, other: Lines) void {
        if (self.data.items.len > 0) self.write("");
        self.data.appendSlice(allocator, other.data.items) catch @panic("allocation failed");
    }
};
pub const SourceLine = struct { number: usize, text: []const u8 };
pub const Field = struct { name: []const u8, value: []const u8 };
pub const Header = struct {
    fields: []Field, invalid: []usize,
    pub fn value(self: Header, name: []const u8) ?[]const u8 {
        for (self.fields) |field| if (equalCase(field.name, name)) return field.value;
        return null;
    }
    pub fn count(self: Header, name: []const u8) usize {
        var result: usize = 0;
        for (self.fields) |field| result += @intFromBool(equalCase(field.name, name));
        return result;
    }
};
pub fn parseFields(source: []const SourceLine) Header {
    var fields: std.ArrayList(Field) = .empty;
    var invalid: std.ArrayList(usize) = .empty;
    var in_field = false;
    for (source) |line| {
        if (whitespace(line.text[0])) {
            if (in_field) {
                const field = &fields.items[fields.items.len - 1];
                field.value = fmt("{s}{s}", .{ field.value, line.text });
            } else append(usize, &invalid, line.number);
            continue;
        }
        const colon = std.mem.indexOfScalar(u8, line.text, ':');
        in_field = colon != null and colon.? > 0;
        if (in_field) for (line.text[0..colon.?]) |character| if (character < 33 or character > 126) { in_field = false; };
        if (in_field) append(Field, &fields, .{ .name = lowercase(line.text[0..colon.?]), .value = line.text[colon.? + 1 ..] }) else append(usize, &invalid, line.number);
    }
    for (fields.items) |*field| field.value = strip(field.value);
    return .{ .fields = fields.items, .invalid = invalid.items };
}
pub fn removeComments(source: []const u8) ?[]const u8 {
    var output: Text = .{};
    var depth: usize = 0;
    var position: usize = 0;
    while (position < source.len) : (position += 1) {
        const character = source[position];
        if (depth == 0) {
            if (character == '(') { depth = 1; output.write(" "); } else output.add("{c}", .{character});
        } else if (character == '\\') { if (position + 1 < source.len) position += 1; } else if (character == '(') depth += 1 else if (character == ')') depth -= 1;
    }
    return if (depth == 0) output.value() else null;
}
pub const word_kind: u16 = 256;
pub const quoted_kind: u16 = 257;
pub const Token = struct { kind: u16, text: []const u8, spaced: bool };
fn wordCharacter(character: u8, mime_mode: bool) bool {
    if (mime_mode) return character >= 33 and character <= 126 and std.mem.indexOfScalar(u8, "()<>@,;:\\\"/[]?=", character) == null;
    return (character >= 'A' and character <= 'Z') or (character >= 'a' and character <= 'z') or (character >= '0' and character <= '9') or std.mem.indexOfScalar(u8, "!#$%&'*+-/=?^_`{|}~", character) != null;
}
pub fn tokenize(source: []const u8, mime_mode: bool) ?[]Token {
    var tokens: std.ArrayList(Token) = .empty;
    const specials = if (mime_mode) "/;=" else "<>:;@,.";
    var position: usize = 0;
    var spaced = false;
    while (position < source.len) {
        const character = source[position];
        if (whitespace(character)) { spaced = true; position += 1; continue; }
        if (character == '(') {
            var depth: usize = 1;
            position += 1;
            while (position < source.len and depth > 0) {
                if (source[position] == '\\') position = @min(position + 2, source.len) else {
                    if (source[position] == '(') depth += 1 else if (source[position] == ')') depth -= 1;
                    position += 1;
                }
            }
            if (depth != 0) return null;
            spaced = true;
            continue;
        }
        var token: Token = .{ .kind = 0, .text = "", .spaced = spaced };
        if (character == '"') {
            var quoted: Text = .{};
            position += 1;
            while (position < source.len and source[position] != '"') : (position += 1) {
                if (source[position] == '\\') { position += 1; if (position == source.len) return null; }
                quoted.add("{c}", .{source[position]});
            }
            if (position == source.len) return null;
            position += 1;
            token.kind = quoted_kind;
            token.text = quoted.value();
        } else if (std.mem.indexOfScalar(u8, specials, character) != null) {
            token.kind = character;
            token.text = source[position .. position + 1];
            position += 1;
        } else if (wordCharacter(character, mime_mode)) {
            const start = position;
            while (position < source.len and wordCharacter(source[position], mime_mode)) position += 1;
            token.kind = word_kind;
            token.text = source[start..position];
        } else return null;
        append(Token, &tokens, token);
        spaced = false;
    }
    return tokens.items;
}
pub const DecodedWord = struct { text: []const u8, decoded: bool = false, failed: bool = false };
pub fn decodeWord(word: []const u8) DecodedWord {
    const original: DecodedWord = .{ .text = word };
    if (word.len < 4 or !std.mem.startsWith(u8, word, "=?") or !std.mem.endsWith(u8, word, "?=")) return original;
    const pieces = split(word[2 .. word.len - 2], '?');
    if (pieces.len != 3 or pieces[0].len == 0 or pieces[1].len == 0 or pieces[2].len == 0) return original;
    const failure: DecodedWord = .{ .text = word, .failed = true };
    if (!equalCase(pieces[0], "us-ascii")) return failure;
    var data: []const u8 = undefined;
    if (eq(pieces[1], "Q") or eq(pieces[1], "q")) {
        var output: Text = .{};
        var i: usize = 0;
        const encoded = pieces[2];
        while (i < encoded.len) {
            var value = encoded[i];
            if (value == '_') { value = ' '; i += 1; } else if (value == '=') {
                if (i + 2 >= encoded.len) return failure;
                const first = mime.hexValue(encoded[i + 1]) orelse return failure;
                const second = mime.hexValue(encoded[i + 2]) orelse return failure;
                value = 16 * first + second;
                i += 3;
            } else i += 1;
            output.add("{c}", .{value});
        }
        data = output.value();
    } else if (eq(pieces[1], "B") or eq(pieces[1], "b")) data = mime.strictBase64(allocator, pieces[2]) orelse return failure else return failure;
    for (data) |value| if (value < 32 or value > 126) return failure;
    return .{ .text = data, .decoded = true };
}
pub const Decoded = struct { text: []const u8, failed: bool };
pub fn decodeUnstructured(source: []const u8) Decoded {
    var output: Text = .{};
    var previous = false;
    var failed = false;
    for (splitWords(source), 0..) |word, i| {
        const decoded = decodeWord(word);
        if (i > 0 and !(previous and decoded.decoded)) output.write(" ");
        output.write(decoded.text);
        previous = decoded.decoded;
        failed = failed or decoded.failed;
    }
    return .{ .text = collapseWhitespace(output.value()), .failed = failed };
}
pub const Parameter = struct { name: []const u8, value: []const u8 };
pub const Parameters = struct {
    main_type: []const u8 = "", subtype: []const u8 = "", values: []Parameter = &.{},
    pub fn get(self: Parameters, name: []const u8) ?[]const u8 {
        for (self.values) |value| if (eq(value.name, name)) return value.value;
        return null;
    }
};
pub fn parseParameters(source: []const u8, with_subtype: bool) ?Parameters {
    const tokens = tokenize(source, true) orelse return null;
    if (tokens.len == 0 or tokens[0].kind != word_kind) return null;
    var result: Parameters = .{ .main_type = lowercase(tokens[0].text) };
    var position: usize = 1;
    if (with_subtype) {
        if (tokens.len < 3 or tokens[1].kind != '/' or tokens[2].kind != word_kind) return null;
        result.subtype = lowercase(tokens[2].text);
        position = 3;
    }
    var parameters: std.ArrayList(Parameter) = .empty;
    while (position < tokens.len) : (position += 4) {
        if (position + 3 >= tokens.len or tokens[position].kind != ';' or tokens[position + 1].kind != word_kind or tokens[position + 2].kind != '=' or (tokens[position + 3].kind != word_kind and tokens[position + 3].kind != quoted_kind)) return null;
        const name = lowercase(tokens[position + 1].text);
        var present = false;
        for (parameters.items) |parameter| if (eq(parameter.name, name)) { present = true; break; };
        if (!present) append(Parameter, &parameters, .{ .name = name, .value = tokens[position + 3].text });
    }
    result.values = parameters.items;
    return result;
}
pub const Entity = struct {
    number: []const u8, main_type: []const u8 = "text", subtype: []const u8 = "plain", parameters: Parameters = .{},
    disposition: ?[]const u8 = null, filename: ?[]const u8 = null, content: []const u8 = "", split: bool = false, children: []*Entity = &.{},
};

const std = @import("std");
const h = @import("headers.zig");
const addresses = @import("addresses.zig");
const dates = @import("dates.zig");
const mime = @import("mime.zig");
const threader = @import("threader.zig");
const Message = threader.Message;
const Container = threader.Container;

fn readMailbox(source: h.Strings) [][]const h.SourceLine {
    var messages: std.ArrayList(std.ArrayList(h.SourceLine)) = .empty;
    for (source, 0..) |raw, i| {
        if (std.mem.startsWith(u8, raw, "From ")) {
            h.append(std.ArrayList(h.SourceLine), &messages, .empty);
            continue;
        }
        var arrows: usize = 0;
        while (arrows < raw.len and raw[arrows] == '>') arrows += 1;
        const line = if (arrows > 0 and std.mem.startsWith(u8, raw[arrows..], "From ")) raw[1..] else raw;
        h.append(h.SourceLine, &messages.items[messages.items.len - 1], .{ .number = i + 1, .text = line });
    }
    const result = h.alloc([]const h.SourceLine, messages.items.len);
    for (messages.items, result) |*message, *target| {
        if (message.items.len > 0 and message.items[message.items.len - 1].text.len == 0) message.items.len -= 1;
        target.* = message.items;
    }
    return result;
}

const Sections = struct { head: []const h.SourceLine, body: []const h.SourceLine };

fn splitSections(source: []const h.SourceLine) Sections {
    for (source, 0..) |line, i| if (line.text.len == 0) return .{ .head = source[0..i], .body = source[i + 1 ..] };
    return .{ .head = source, .body = &.{} };
}

fn isMessageId(source: []const u8) bool {
    if (source.len < 3 or source[0] != '<' or source[source.len - 1] != '>') return false;
    const inside = source[1 .. source.len - 1];
    if (inside[0] == '@' or inside[inside.len - 1] == '@') return false;
    var ats: usize = 0;
    for (inside) |character| {
        if (character < 33 or character > 126 or std.mem.indexOfScalar(u8, "<>()\"\\", character) != null) return false;
        ats += @intFromBool(character == '@');
    }
    return ats == 1;
}

fn extractIds(source: []const u8) std.ArrayList([]const u8) {
    var result: std.ArrayList([]const u8) = .empty;
    var position: usize = 0;
    while (std.mem.indexOfScalarPos(u8, source, position, '<')) |start| {
        const end = std.mem.indexOfScalarPos(u8, source, start + 1, '>') orelse break;
        const id = source[start .. end + 1];
        if (isMessageId(id)) h.append([]const u8, &result, id);
        position = end + 1;
    }
    return result;
}

fn parseEntity(message: *Message, number: []const u8, header: h.Header, source: []const h.SourceLine, enabled: bool) *h.Entity {
    const entity = &h.alloc(h.Entity, 1)[0];
    entity.* = .{ .number = number };
    if (enabled) {
        if (header.value("Content-Type")) |value| {
            if (h.parseParameters(value, true)) |parsed| {
                entity.main_type = parsed.main_type;
                entity.subtype = parsed.subtype;
                entity.parameters = parsed;
            } else message.problems.add("bad Content-Type in part {s}", .{number});
        }
        if (header.value("Content-Disposition")) |value| {
            if (h.parseParameters(value, false)) |parsed| {
                entity.disposition = parsed.main_type;
                entity.filename = parsed.get("filename");
            } else message.problems.add("bad Content-Disposition in part {s}", .{number});
        }
    }
    if (entity.filename == null or entity.filename.?.len == 0) entity.filename = entity.parameters.get("name");
    if (h.eq(entity.main_type, "text")) {
        if (entity.parameters.get("charset")) |charset| {
            if (!h.equalCase(charset, "us-ascii")) message.problems.add("unsupported charset \"{s}\" in part {s}", .{ h.lowercase(charset), number });
        }
    }
    if (enabled and h.eq(entity.main_type, "multipart")) {
        const boundary = entity.parameters.get("boundary") orelse "";
        if (boundary.len == 0) {
            message.problems.add("missing boundary in part {s}", .{number});
        } else {
            entity.split = true;
            const opening = h.fmt("--{s}", .{boundary});
            const closing = h.fmt("--{s}--", .{boundary});
            var parts: std.ArrayList([]const h.SourceLine) = .empty;
            var start: ?usize = null;
            var closed = false;
            for (source, 0..) |line, i| {
                const text = h.rstrip(line.text);
                if (h.eq(text, closing)) {
                    if (start) |value| h.append([]const h.SourceLine, &parts, source[value..i]);
                    closed = true;
                    start = null;
                    break;
                }
                if (h.eq(text, opening)) {
                    if (start) |value| h.append([]const h.SourceLine, &parts, source[value..i]);
                    start = i + 1;
                }
            }
            if (start) |value| h.append([]const h.SourceLine, &parts, source[value..]);
            if (parts.items.len == 0) message.problems.add("no parts in part {s}", .{number}) else if (!closed) message.problems.add("unterminated multipart in part {s}", .{number});
            var children: std.ArrayList(*h.Entity) = .empty;
            for (parts.items, 0..) |part, i| {
                const sections = splitSections(part);
                const child_header = h.parseFields(sections.head);
                for (child_header.invalid) |line_number| message.problems.add("bad header line {d}", .{line_number});
                h.append(*h.Entity, &children, parseEntity(message, h.fmt("{s}.{d}", .{ number, i + 1 }), child_header, sections.body, true));
            }
            entity.children = children.items;
            return entity;
        }
    }
    const body = h.alloc([]const u8, source.len);
    for (source, body) |line, *text| text.* = line.text;
    const original = h.join(body, "\n");
    const encoding = if (enabled) h.lowercase(header.value("Content-Transfer-Encoding") orelse "7bit") else "7bit";
    if (h.eq(encoding, "base64")) {
        if (mime.decodeBase64Body(h.allocator, original)) |content| entity.content = content else {
            message.problems.add("bad base64 in part {s}", .{number});
        }
    } else if (h.eq(encoding, "quoted-printable")) {
        const decoded = mime.decodeQuotedPrintable(h.allocator, original);
        entity.content = decoded.text;
        if (decoded.failed) message.problems.add("bad quoted-printable in part {s}", .{number});
    } else {
        entity.content = original;
        if (!h.eq(encoding, "7bit") and !h.eq(encoding, "8bit") and !h.eq(encoding, "binary")) message.problems.add("unknown encoding \"{s}\" in part {s}", .{ encoding, number });
    }
    return entity;
}

fn readRecipients(message: *Message, header: h.Header, name: []const u8) h.Strings {
    const value = header.value(name) orelse return &.{};
    const parsed = addresses.parse(value) orelse {
        message.problems.add("bad {s}", .{name});
        return &.{};
    };
    var result: std.ArrayList([]const u8) = .empty;
    for (parsed.items) |address| {
        if (address.group) {
            for (address.members) |member| h.append([]const u8, &result, member.address);
        } else h.append([]const u8, &result, address.mailbox.?.address);
    }
    if (parsed.encoding_error) message.problems.add("bad encoded word in {s}", .{name});
    return result.items;
}

fn processMessage(message: *Message, source: []const h.SourceLine, earlier: []const Message) void {
    const checked = [_][]const u8{ "From", "To", "Cc", "Subject", "Date", "Message-ID", "In-Reply-To", "References", "MIME-Version", "Content-Type", "Content-Transfer-Encoding", "Content-Disposition" };
    const sections = splitSections(source);
    const header = h.parseFields(sections.head);
    for (header.invalid) |line_number| message.problems.add("bad header line {d}", .{line_number});
    for (checked) |name| if (header.count(name) > 1) message.problems.add("duplicate {s}", .{name});
    if (header.value("From")) |value| {
        if (addresses.parse(value)) |parsed| {
            if (parsed.items.len == 1 and !parsed.items[0].group) {
                message.sender = parsed.items[0].mailbox;
                if (parsed.encoding_error) message.problems.write("bad encoded word in From");
            } else message.problems.write("bad From");
        } else message.problems.write("bad From");
    } else message.problems.write("missing From");
    message.to = readRecipients(message, header, "To");
    message.cc = readRecipients(message, header, "Cc");
    const subject = h.decodeUnstructured(header.value("Subject") orelse "");
    message.subject = subject.text;
    if (subject.failed) message.problems.write("bad encoded word in Subject");
    message.base_subject = subject.text;
    while (message.base_subject.len >= 3 and h.equalCase(message.base_subject[0..3], "re:")) {
        message.base_subject = std.mem.trimStart(u8, message.base_subject[3..], " ");
        message.reply = true;
    }
    if (header.value("Date")) |value| {
        const parsed = dates.parse(value);
        message.date = parsed.seconds;
        if (parsed.error_text) |error_text| message.problems.write(error_text);
    } else message.problems.write("missing Date");
    if (header.value("Message-ID")) |value| {
        if (!isMessageId(value)) {
            message.problems.write("bad Message-ID");
        } else {
            var duplicate: ?usize = null;
            for (earlier) |previous| {
                if (h.eq(previous.id, value)) { duplicate = previous.number; break; }
            }
            if (duplicate) |number| message.problems.add("Message-ID already used by message {d}", .{number}) else message.id = value;
        }
    } else message.problems.write("missing Message-ID");
    var references = extractIds(header.value("References") orelse "");
    const replies = extractIds(header.value("In-Reply-To") orelse "");
    if (replies.items.len > 0 and (references.items.len == 0 or !h.eq(references.items[references.items.len - 1], replies.items[0]))) h.append([]const u8, &references, replies.items[0]);
    message.references = references.items;
    var enabled = false;
    if (header.value("MIME-Version")) |value| {
        if (h.removeComments(value)) |clean| {
            var compact: h.Text = .{};
            for (clean) |character| if (!h.whitespace(character)) compact.add("{c}", .{character});
            enabled = h.eq(compact.value(), "1.0");
        }
        if (!enabled) message.problems.write("bad MIME-Version");
    }
    message.body = parseEntity(message, "1", header, sections.body, enabled);
}

const LogicalLine = struct { depth: usize, text: []const u8, flowing: bool = false };

fn quotePrefix(depth: usize) []const u8 {
    if (depth == 0) return "";
    const result = h.alloc(u8, depth + 1);
    @memset(result[0..depth], '>');
    result[depth] = ' ';
    return result;
}

fn wrap(text: []const u8, prefix: []const u8, result: *h.Lines) void {
    var current: []const u8 = "";
    for (h.splitWords(text)) |word| {
        if (current.len > 0 and current.len + 1 + word.len > 72) {
            result.add("{s}{s}", .{ prefix, current });
            current = word;
        } else current = if (current.len > 0) h.fmt("{s} {s}", .{ current, word }) else word;
    }
    result.add("{s}{s}", .{ prefix, current });
}

fn flowedLines(content: []const u8, delete_space: bool) h.Lines {
    var result: h.Lines = .{};
    if (content.len == 0) return result;
    var logical: std.ArrayList(LogicalLine) = .empty;
    for (h.split(content, '\n')) |line| {
        var depth: usize = 0;
        while (depth < line.len and line[depth] == '>') depth += 1;
        var text = line[depth..];
        if (text.len > 0 and text[0] == ' ') text = text[1..];
        const flowing = text.len > 0 and text[text.len - 1] == ' ' and !h.eq(text, "-- ");
        const previous = if (logical.items.len > 0) &logical.items[logical.items.len - 1] else null;
        if (previous != null and previous.?.flowing and previous.?.depth == depth) {
            const left = if (delete_space) previous.?.text[0 .. previous.?.text.len - 1] else previous.?.text;
            previous.?.text = h.fmt("{s}{s}", .{ left, text });
            previous.?.flowing = flowing;
        } else h.append(LogicalLine, &logical, .{ .depth = depth, .text = text, .flowing = flowing });
    }
    for (logical.items) |line| wrap(line.text, quotePrefix(line.depth), &result);
    return result;
}

fn referenceValue(name: []const u8) ?u8 {
    const names = [_][]const u8{ "amp", "lt", "gt", "quot", "apos", "nbsp" };
    const values = [_]u8{ '&', '<', '>', '"', '\'', ' ' };
    for (names, values) |candidate, value| if (h.eq(name, candidate)) return value;
    if (name.len >= 2 and name.len <= 4 and name[0] == '#') {
        for (name[1..]) |character| if (character < '0' or character > '9') return null;
        const value = h.number(name[1..]);
        if (value >= 32 and value <= 126) return @intCast(value);
    }
    return null;
}

fn replaceReferences(text: []const u8) []const u8 {
    var result: h.Text = .{};
    var position: usize = 0;
    while (position < text.len) {
        if (text[position] == '&') {
            if (std.mem.indexOfScalarPos(u8, text, position + 1, ';')) |end| {
                if (referenceValue(text[position + 1 .. end])) |replacement| {
                    result.add("{c}", .{replacement});
                    position = end + 1;
                    continue;
                }
            }
        }
        result.add("{c}", .{text[position]});
        position += 1;
    }
    return result.value();
}

fn tagCharacter(character: u8) bool {
    return (character >= 'A' and character <= 'Z') or (character >= 'a' and character <= 'z') or (character >= '0' and character <= '9');
}

fn paragraphTag(name: []const u8) bool {
    const names = [_][]const u8{ "p", "div", "ul", "ol", "table", "tr", "blockquote", "h1", "h2", "h3", "h4", "h5", "h6" };
    for (names) |candidate| if (h.eq(name, candidate)) return true;
    return false;
}

fn htmlBlocks(content: []const u8) []LogicalLine {
    var blocks: std.ArrayList(LogicalLine) = .empty;
    var depth: usize = 0;
    var text: h.Text = .{};
    var hide: ?[]const u8 = null;
    var position: usize = 0;
    while (position < content.len) {
        const closing = if (content[position] == '<') std.mem.indexOfScalarPos(u8, content, position + 1, '>') else null;
        if (closing == null) {
            if (hide == null) text.add("{c}", .{content[position]});
            position += 1;
            continue;
        }
        const inside = content[position + 1 .. closing.?];
        position = closing.? + 1;
        const end_tag = inside.len > 0 and inside[0] == '/';
        const start = inside[@intFromBool(end_tag)..];
        var size: usize = 0;
        while (size < start.len and tagCharacter(start[size])) size += 1;
        const name = h.lowercase(start[0..size]);
        if (hide) |hidden| {
            if (end_tag and h.eq(name, hidden)) hide = null;
        } else if (!end_tag and (h.eq(name, "head") or h.eq(name, "style") or h.eq(name, "script"))) {
            hide = name;
        } else if (h.eq(name, "br") or (h.eq(name, "li") and !end_tag)) {
            h.append(LogicalLine, &blocks, .{ .depth = depth, .text = text.value() });
            text = .{};
            if (h.eq(name, "li")) text.write("* ");
        } else if (paragraphTag(name)) {
            h.append(LogicalLine, &blocks, .{ .depth = depth, .text = text.value() });
            h.append(LogicalLine, &blocks, .{ .depth = depth, .text = "" });
            text = .{};
            if (h.eq(name, "blockquote")) {
                if (!end_tag) depth += 1 else if (depth > 0) depth -= 1;
            }
        }
    }
    h.append(LogicalLine, &blocks, .{ .depth = depth, .text = text.value() });
    return blocks.items;
}

fn htmlLines(content: []const u8) h.Lines {
    var result: h.Lines = .{};
    for (htmlBlocks(content)) |block| {
        const replaced = h.alloc(u8, block.text.len);
        for (block.text, replaced) |character, *target| target.* = if (character == '\n') ' ' else character;
        const text = std.mem.trim(u8, replaceReferences(h.collapseWhitespace(replaced)), " ");
        if (text.len > 0) wrap(text, quotePrefix(block.depth), &result) else {
            if (result.data.items.len > 0 and result.data.items[result.data.items.len - 1].len > 0) result.write("");
        }
    }
    while (result.data.items.len > 0 and result.data.items[result.data.items.len - 1].len == 0) result.data.items.len -= 1;
    return result;
}

fn collectTextParts(entity: *h.Entity, allow_html: bool) []*h.Entity {
    var result: std.ArrayList(*h.Entity) = .empty;
    if (!entity.split) {
        if (!h.eq(entity.main_type, "text") or (entity.disposition != null and h.eq(entity.disposition.?, "attachment"))) return result.items;
        if (h.eq(entity.subtype, "plain") or (allow_html and h.eq(entity.subtype, "html"))) h.append(*h.Entity, &result, entity);
        return result.items;
    }
    if (h.eq(entity.subtype, "alternative")) {
        for ([_]bool{ false, true }) |html| {
            for (entity.children) |child| {
                const parts = collectTextParts(child, html);
                if (parts.len > 0) return parts;
            }
        }
        return result.items;
    }
    for (entity.children) |child| {
        for (collectTextParts(child, allow_html)) |part| h.append(*h.Entity, &result, part);
    }
    return result.items;
}

const Display = struct { format: []const u8, lines: h.Lines };

fn displayLines(entity: *h.Entity) Display {
    if (h.eq(entity.subtype, "html")) return .{ .format = "html", .lines = htmlLines(entity.content) };
    const format = entity.parameters.get("format") orelse "";
    if (h.equalCase(format, "flowed")) {
        const delete_space = h.equalCase(entity.parameters.get("delsp") orelse "", "yes");
        return .{ .format = "flowed", .lines = flowedLines(entity.content, delete_space) };
    }
    var result: h.Lines = .{};
    if (entity.content.len > 0) for (h.split(entity.content, '\n')) |line| result.write(line);
    return .{ .format = "plain", .lines = result };
}

fn subjectNotation(subject: []const u8) []const u8 {
    return if (subject.len > 0) subject else "(no subject)";
}

fn dateNotation(date: ?i64) []const u8 {
    return if (date) |seconds| dates.formatUtc(seconds) else "invalid";
}

const ThreadStats = struct {
    messages: usize = 0,
    depth: usize = 0,
    senders: std.ArrayList([]const u8) = .empty,
    rows: h.Lines = .{},
    first: ?i64 = null,
    last: ?i64 = null,
};

fn walkThread(container: *Container, number: usize, depth: usize, prefix: []const u8, stem: []const u8, stats: *ThreadStats) void {
    stats.depth = @max(stats.depth, depth);
    if (container.message) |message| {
        stats.messages += 1;
        message.thread = number;
        message.depth = depth;
        message.parent = if (container.parent) |parent| parent.message else null;
        if (message.sender) |sender| {
            var present = false;
            for (stats.senders.items) |address| if (h.eq(address, sender.address)) { present = true; };
            if (!present) h.append([]const u8, &stats.senders, sender.address);
        }
        if (message.date) |seconds| {
            if (stats.first == null or seconds < stats.first.?) stats.first = seconds;
            if (stats.last == null or seconds > stats.last.?) stats.last = seconds;
        }
        stats.rows.add("{s}[{d}] {s} {s} {s}", .{ prefix, message.number, dateNotation(message.date), if (message.sender) |sender| sender.address else "-", subjectNotation(message.subject) });
    } else if (container.subject) |subject| {
        stats.rows.add("{s}[subject] {s}", .{ prefix, subject });
    } else stats.rows.add("{s}[missing] {s}", .{ prefix, container.id });
    for (container.children.items, 0..) |child, i| {
        const last = i + 1 == container.children.items.len;
        walkThread(child, number, depth + 1, h.fmt("{s}{s}", .{ stem, if (last) "`- " else "+- " }), h.fmt("{s}{s}", .{ stem, if (last) "   " else "|  " }), stats);
    }
}

fn threadReport(root: *Container, number: usize) h.Lines {
    var stats: ThreadStats = .{};
    walkThread(root, number, 0, "", "", &stats);
    var result: h.Lines = .{};
    result.add("thread {d} messages {d} depth {d} senders {d}", .{ number, stats.messages, stats.depth, stats.senders.items.len });
    if (stats.first) |first| result.add("span {s} .. {s}", .{ dates.formatUtc(first), dates.formatUtc(stats.last.?) }) else result.write("span -");
    result.add("subject {s}", .{subjectNotation(root.subject orelse threader.rootSubject(root))});
    for (stats.rows.data.items) |line| result.write(line);
    return result;
}

fn entityLines(entity: *h.Entity, result: *h.Lines) void {
    var line: h.Text = .{};
    line.add("part {s} {s}/{s}", .{ entity.number, entity.main_type, entity.subtype });
    if (!entity.split) {
        line.add(" {d}", .{entity.content.len});
        if (entity.disposition) |disposition| line.add(" {s}", .{disposition});
        if (entity.filename) |filename| if (filename.len > 0) line.add(" \"{s}\"", .{filename});
    }
    result.write(line.value());
    if (entity.split) for (entity.children) |child| entityLines(child, result);
}

fn messageReport(message: *Message) h.Lines {
    var result: h.Lines = .{};
    result.add("message {d}", .{message.number});
    result.add("id {s}", .{if (message.id.len > 0) message.id else "-"});
    result.add("date {s}", .{dateNotation(message.date)});
    const sender_text = if (message.sender) |sender| (if (sender.name.len > 0) h.fmt("{s} <{s}>", .{ sender.name, sender.address }) else sender.address) else "-";
    result.add("from {s}", .{sender_text});
    result.add("to {s}", .{if (message.to.len > 0) h.join(message.to, ", ") else "-"});
    result.add("cc {s}", .{if (message.cc.len > 0) h.join(message.cc, ", ") else "-"});
    result.add("subject {s}", .{subjectNotation(message.subject)});
    result.add("refs {s}", .{if (message.references.len > 0) h.join(message.references, " ") else "-"});
    result.add("thread {d} depth {d} parent {s}", .{ message.thread, message.depth, if (message.parent) |parent| h.fmt("{d}", .{parent.number}) else "-" });
    entityLines(message.body, &result);
    return result;
}

fn bodyReport(request: []const u8, messages: []Message) h.Lines {
    var result: h.Lines = .{};
    result.add("request {s}", .{request});
    var found: ?*Message = null;
    for (messages) |*message| {
        if (message.id.len > 0 and h.eq(message.id, request)) { found = message; break; }
    }
    if (found == null) {
        result.write("not found");
        return result;
    }
    const parts = collectTextParts(found.?.body, true);
    result.add("message {d} text parts {d}", .{ found.?.number, parts.len });
    for (parts) |part| {
        const display = displayLines(part);
        var quoted: usize = 0;
        var signature: usize = 0;
        for (display.lines.data.items, 0..) |*line, i| {
            line.* = h.rstrip(line.*);
            if (line.*.len > 0 and line.*[0] == '>') quoted += 1;
            if (h.eq(line.*, "--")) signature = display.lines.data.items.len - i - 1;
        }
        result.add("part {s} {s} lines {d} quoted {d} signature {d}", .{ part.number, display.format, display.lines.data.items.len, quoted, signature });
        for (display.lines.data.items) |line| result.add("{s}{s}", .{ if (line.len > 0) "| " else "|", line });
    }
    return result;
}

const SenderStats = struct {
    address: []const u8,
    name: []const u8 = "",
    count: usize = 0,
    threads: std.ArrayList(usize) = .empty,
    first: ?i64 = null,
    last: ?i64 = null,
};

fn senderLessThan(_: void, first: SenderStats, second: SenderStats) bool {
    if (first.count != second.count) return first.count > second.count;
    return std.mem.order(u8, first.address, second.address) == .lt;
}

fn csvField(source: []const u8) []const u8 {
    if (std.mem.indexOfAny(u8, source, ",\"") == null) return source;
    var result: h.Text = .{};
    result.write("\"");
    for (source) |character| {
        if (character == '"') result.write("\"\"") else result.add("{c}", .{character});
    }
    result.write("\"");
    return result.value();
}

fn sendersReport(messages: []Message) h.Lines {
    var stats: std.ArrayList(SenderStats) = .empty;
    for (messages) |message| {
        const sender = message.sender orelse continue;
        var index: usize = 0;
        while (index < stats.items.len and !h.eq(stats.items[index].address, sender.address)) index += 1;
        if (index == stats.items.len) h.append(SenderStats, &stats, .{ .address = sender.address });
        const entry = &stats.items[index];
        entry.count += 1;
        var present = false;
        for (entry.threads.items) |number| if (number == message.thread) { present = true; };
        if (!present) h.append(usize, &entry.threads, message.thread);
        if (message.date) |seconds| {
            if (entry.first == null or seconds < entry.first.?) entry.first = seconds;
            if (entry.last == null or seconds > entry.last.?) entry.last = seconds;
        }
        if (sender.name.len > 0) entry.name = sender.name;
    }
    std.mem.sort(SenderStats, stats.items, {}, senderLessThan);
    var result: h.Lines = .{};
    result.write("address,name,messages,threads,first,last");
    for (stats.items) |entry| {
        result.add("{s},{s},{d},{d},{s},{s}", .{ entry.address, csvField(entry.name), entry.count, entry.threads.items.len, if (entry.first) |seconds| dates.formatUtc(seconds) else "-", if (entry.last) |seconds| dates.formatUtc(seconds) else "-" });
    }
    return result;
}

fn malformedReport(messages: []Message) h.Lines {
    var malformed: usize = 0;
    var problems: usize = 0;
    for (messages) |message| {
        malformed += @intFromBool(message.problems.data.items.len > 0);
        problems += message.problems.data.items.len;
    }
    var result: h.Lines = .{};
    result.add("messages {d} malformed {d} problems {d}", .{ messages.len, malformed, problems });
    for (messages) |message| {
        for (message.problems.data.items) |problem| result.add("message {d}: {s}", .{ message.number, problem });
    }
    return result;
}

fn writeLines(io: std.Io, name: []const u8, source: h.Lines) !void {
    var text: h.Text = .{};
    for (source.data.items) |line| text.add("{s}\n", .{line});
    try std.Io.Dir.cwd().writeFile(io, .{ .sub_path = h.fmt("output/{s}", .{name}), .data = text.value() });
}

pub fn main(init: std.process.Init) !void {
    var arena = std.heap.ArenaAllocator.init(init.gpa);
    defer arena.deinit();
    h.allocator = arena.allocator();
    const raw = try std.Io.Dir.cwd().readFileAlloc(init.io, "input/mailbox.mbox", h.allocator, .unlimited);
    const source = readMailbox(h.lines(raw));
    const messages = h.alloc(Message, source.len);
    for (source, 0..) |lines, i| {
        messages[i] = .{ .number = i + 1 };
        processMessage(&messages[i], lines, messages[0..i]);
    }
    const roots = threader.build(messages);
    var threads: h.Lines = .{};
    var message_lines: h.Lines = .{};
    var bodies: h.Lines = .{};
    for (roots, 0..) |root, i| threads.paragraph(threadReport(root, i + 1));
    for (messages) |*message| {
        if (message.parent) |parent| {
            if (message.date != null and parent.date != null and message.date.? < parent.date.?) message.problems.add("dated before parent message {d}", .{parent.number});
        }
        message_lines.paragraph(messageReport(message));
    }
    const requests = try std.Io.Dir.cwd().readFileAlloc(init.io, "input/requests.txt", h.allocator, .unlimited);
    for (h.lines(requests)) |request| bodies.paragraph(bodyReport(request, messages));
    try std.Io.Dir.cwd().createDirPath(init.io, "output");
    try writeLines(init.io, "threads.txt", threads);
    try writeLines(init.io, "messages.txt", message_lines);
    try writeLines(init.io, "bodies.txt", bodies);
    try writeLines(init.io, "senders.csv", sendersReport(messages));
    try writeLines(init.io, "malformed.txt", malformedReport(messages));
}

const std = @import("std");
fn add(list: *std.ArrayList(u8), allocator: std.mem.Allocator, value: u8) void { list.append(allocator, value) catch @panic("allocation failed"); }
pub fn hexValue(character: u8) ?u8 {
    if (character >= '0' and character <= '9') return character - '0';
    if (character >= 'A' and character <= 'F') return character - 'A' + 10;
    if (character >= 'a' and character <= 'f') return character - 'a' + 10;
    return null;
}
pub fn strictBase64(allocator: std.mem.Allocator, source: []const u8) ?[]const u8 {
    if (source.len % 4 != 0) return null;
    var end = source.len;
    while (end > 0 and source[end - 1] == '=') end -= 1;
    if (source.len - end >= 3) return null;
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    var output: std.ArrayList(u8) = .empty;
    var buffer: u16 = 0;
    var bits: u4 = 0;
    for (source[0..end]) |character| {
        const value = std.mem.indexOfScalar(u8, alphabet, character) orelse return null;
        buffer = (buffer << 6) | @as(u16, @intCast(value));
        bits += 6;
        if (bits >= 8) {
            bits -= 8;
            add(&output, allocator, @intCast(buffer >> bits));
            buffer &= (@as(u16, 1) << bits) - 1;
        }
    }
    return output.items;
}
pub fn decodeBase64Body(allocator: std.mem.Allocator, source: []const u8) ?[]const u8 {
    var compact: std.ArrayList(u8) = .empty;
    for (source) |character| if (character != ' ' and character != '\t' and character != '\n') { add(&compact, allocator, character); };
    const bytes = strictBase64(allocator, compact.items) orelse return null;
    var output: std.ArrayList(u8) = .empty;
    var i: usize = 0;
    while (i < bytes.len) : (i += 1) {
        var value = bytes[i];
        if (value == 13 and i + 1 < bytes.len and bytes[i + 1] == 10) { value = 10; i += 1; }
        if (value != 9 and value != 10 and (value < 32 or value > 126)) return null;
        add(&output, allocator, value);
    }
    return output.items;
}
pub const Decoded = struct { text: []const u8, failed: bool };
pub fn decodeQuotedPrintable(allocator: std.mem.Allocator, source: []const u8) Decoded {
    var output: std.ArrayList(u8) = .empty;
    var failed = false;
    var start: usize = 0;
    while (true) {
        const end = if (std.mem.indexOfScalarPos(u8, source, start, '\n')) |index| index else source.len;
        var line = std.mem.trimEnd(u8, source[start..end], " \t");
        const soft = line.len > 0 and line[line.len - 1] == '=';
        if (soft) line = line[0 .. line.len - 1];
        var position: usize = 0;
        while (position < line.len) {
            var value: ?u8 = null;
            if (line[position] == '=' and position + 2 < line.len) {
                if (hexValue(line[position + 1])) |first| {
                    if (hexValue(line[position + 2])) |second| {
                        const decoded = 16 * first + second;
                        if (decoded == 9 or (decoded >= 32 and decoded <= 126)) value = decoded;
                    }
                }
            }
            if (value) |decoded| { add(&output, allocator, decoded); position += 3; } else {
                failed = failed or line[position] == '=';
                add(&output, allocator, line[position]);
                position += 1;
            }
        }
        if (end == source.len) break;
        if (!soft) add(&output, allocator, '\n');
        start = end + 1;
    }
    return .{ .text = output.items, .failed = failed };
}

const std = @import("std");
const h = @import("headers.zig");
const addresses = @import("addresses.zig");

pub const Message = struct {
    number: usize,
    thread: usize = 0,
    depth: usize = 0,
    sender: ?addresses.Mailbox = null,
    to: h.Strings = &.{},
    cc: h.Strings = &.{},
    subject: []const u8 = "",
    base_subject: []const u8 = "",
    reply: bool = false,
    date: ?i64 = null,
    id: []const u8 = "",
    references: h.Strings = &.{},
    body: *h.Entity = undefined,
    problems: h.Lines = .{},
    parent: ?*Message = null,
};

pub const Container = struct {
    id: []const u8,
    subject: ?[]const u8 = null,
    message: ?*Message = null,
    parent: ?*Container = null,
    children: std.ArrayList(*Container) = .empty,
};

fn newContainer(id: []const u8) *Container {
    const container = &h.alloc(Container, 1)[0];
    container.* = .{ .id = id };
    return container;
}

fn containerOf(all: *std.ArrayList(*Container), id: []const u8) *Container {
    for (all.items) |container| if (container.id.len > 0 and h.eq(container.id, id)) return container;
    const container = newContainer(id);
    h.append(*Container, all, container);
    return container;
}

fn ancestor(first: *Container, second: *Container) bool {
    var current: ?*Container = second;
    while (current) |container| {
        if (first == container) return true;
        current = container.parent;
    }
    return false;
}

fn adopt(parent: *Container, child: *Container) void {
    child.parent = parent;
    h.append(*Container, &parent.children, child);
}

fn prune(containers: []*Container, at_root: bool) std.ArrayList(*Container) {
    var result: std.ArrayList(*Container) = .empty;
    for (containers) |container| {
        container.children = prune(container.children.items, false);
        if (container.message != null or (at_root and container.children.items.len >= 2)) {
            h.append(*Container, &result, container);
        } else {
            for (container.children.items) |child| {
                child.parent = if (at_root) null else container.parent;
                h.append(*Container, &result, child);
            }
        }
    }
    return result;
}

pub fn compareMessages(first: *const Message, second: *const Message) std.math.Order {
    if ((first.date != null) != (second.date != null)) return if (first.date != null) .lt else .gt;
    if (first.date) |value| if (value != second.date.?) return std.math.order(value, second.date.?);
    const id_order = std.mem.order(u8, first.id, second.id);
    return if (id_order != .eq) id_order else std.math.order(first.number, second.number);
}

fn key(container: *Container) *Message {
    if (container.message) |message| return message;
    var minimum: ?*Message = null;
    for (container.children.items) |child| {
        const candidate = key(child);
        if (minimum == null or compareMessages(candidate, minimum.?) == .lt) minimum = candidate;
    }
    return minimum.?;
}

fn lessThan(_: void, first: *Container, second: *Container) bool {
    return compareMessages(key(first), key(second)) == .lt;
}

fn sortContainers(containers: []*Container) void {
    for (containers) |container| sortContainers(container.children.items);
    std.mem.sort(*Container, containers, {}, lessThan);
}

pub fn rootSubject(root: *Container) []const u8 {
    return if (root.message) |message| message.base_subject else root.children.items[0].message.?.base_subject;
}

fn mergeSubjects(roots: []*Container) []*Container {
    var result: std.ArrayList(*Container) = .empty;
    const handled = h.alloc(bool, roots.len);
    @memset(handled, false);
    for (roots, 0..) |root, i| {
        if (handled[i]) continue;
        const subject = rootSubject(root);
        var group: std.ArrayList(*Container) = .empty;
        for (roots[i..], i..) |candidate, j| {
            if (j == i or (subject.len > 0 and h.eq(subject, rootSubject(candidate)))) {
                handled[j] = true;
                h.append(*Container, &group, candidate);
            }
        }
        if (group.items.len == 1) {
            h.append(*Container, &result, group.items[0]);
            continue;
        }
        var target: ?*Container = null;
        var original: ?*Container = null;
        var originals: usize = 0;
        for (group.items) |container| {
            if (container.message) |message| {
                if (!message.reply) { original = container; originals += 1; }
            } else if (target == null) target = container;
        }
        if (target == null and originals == 1) target = original;
        if (target == null) {
            target = newContainer("");
            target.?.subject = subject;
        }
        for (group.items) |container| {
            if (container == target.?) continue;
            if (container.message != null) adopt(target.?, container) else {
                for (container.children.items) |child| adopt(target.?, child);
            }
        }
        h.append(*Container, &result, target.?);
    }
    return result.items;
}

pub fn build(messages: []Message) []*Container {
    var all: std.ArrayList(*Container) = .empty;
    for (messages) |*message| {
        const container = if (message.id.len > 0) containerOf(&all, message.id) else blk: {
            const anonymous = newContainer("");
            h.append(*Container, &all, anonymous);
            break :blk anonymous;
        };
        container.message = message;
        const references = h.alloc(*Container, message.references.len);
        for (message.references, references) |id, *reference| reference.* = containerOf(&all, id);
        if (references.len > 0) {
            for (references[0 .. references.len - 1], references[1..]) |first, second| {
                if (second.parent == null and !ancestor(second, first)) adopt(first, second);
            }
        }
        if (container.parent) |parent| {
            for (parent.children.items, 0..) |sibling, i| {
                if (sibling == container) { _ = parent.children.orderedRemove(i); break; }
            }
            container.parent = null;
        }
        if (references.len > 0 and !ancestor(container, references[references.len - 1])) adopt(references[references.len - 1], container);
    }
    var roots: std.ArrayList(*Container) = .empty;
    for (all.items) |container| if (container.parent == null) h.append(*Container, &roots, container);
    roots = prune(roots.items, true);
    sortContainers(roots.items);
    const merged = mergeSubjects(roots.items);
    sortContainers(merged);
    return merged;
}
